import json
from pathlib import Path
p=Path("docs/course-review-20261019/reviews/rv1019_reader_ch01b/reader-original-01.json")
r=json.loads(p.read_text())
out={"source_freeze":r["source_freeze"],"reading_plan":r["reading_plan"],"pages":[]}
for page in r["pages"]:
    record={k:page[k] for k in ["page_id","session","source_sha256","figures_sha256","verdict","ai_estimate"]}
    pending=[]
    for note in page["session_evidence"]["notes"]:
        n=json.loads(Path(note["path"]).read_text())
        for i,c in enumerate(n["concept_checks"]):
            if c["verdict"]!="已足夠":
                pending.append({"note":note,"unit_index":n["unit_index"],"concept_index":i,"check":c,"confusion_and_quote":n["confusion_and_quote"]})
    record["pending"]=pending
    out["pages"].append(record)
print(json.dumps(out,ensure_ascii=False,indent=2))

